if not Path("app/static/mobile").is_dir():
    raise SystemExit("Lancez ce script depuis la racine du projet (le dossier qui contient le dossier app).")

# Anciennes polices (Geist), remplacees par les nouvelles
for ancien in ("app/static/mobile/fonts/geist-latin-wght-normal.woff2", "app/static/mobile/fonts/geist-mono-latin-wght-normal.woff2"):
    if Path(ancien).exists():
        Path(ancien).unlink()
        print("supprime:", ancien)

with zipfile.ZipFile(io.BytesIO(base64.b64decode("".join(ARCHIVE.split())))) as z:
    for nom in z.namelist():
        if nom.endswith("/"):
            continue
        cible = Path(nom)
        cible.parent.mkdir(parents=True, exist_ok=True)
        cible.write_bytes(z.read(nom))
        print("ecrit:", nom)
print("Termine. Lancez pytest -q, relancez le serveur, puis Ctrl+F5 sur la page. Sur le telephone, fermez et rouvrez l'application.")